import {createHash}from'node:crypto';
export function publicAgentRegistration(networkId,canonicalOwner,pair,currentSelector,registeredAtMs=0,expiresAtMs=200000){const original=Buffer.from('PUBLIC ONLY protected record fixture, NOT admitted: '+pair.pkA+pair.pkB);return{version:'1',purpose:'PRODUCT-SESSION-AI-TASK-ACTION',networkId,canonicalOwner,registrationId:'PUBLIC-independent-agent',registrationDigest:createHash('sha256').update(original).digest('hex'),keyEpoch:'18446744073709551615',pkA:pair.pkA,pkB:pair.pkB,...currentSelector,protectedResourceRef:'PUBLIC-protected-agent-record',registeredAtMs,expiresAtMs};}
